mapper.select:
select count(1) AS new_complain_count
from w_complain
where flag != -1 AND create_time between #{startTime} and #{endTime}

SELECT rs.* FROM ( ( SELECT a.complain_id, w.form_id, a.user_id, a.typef, a.subject, a.content, (select name from b_organization where organization_id = a.organization_id) as serviceCompany, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, DATE_FORMAT(a.process_time, '%Y-%m-%d %T') AS process_time,a.flag, a.create_user_id, JSON_UNQUOTE(JSON_EXTRACT(w.content, '$.businessName')) AS business_name, d.code AS order_code, d.status AS order_status, DATE_FORMAT( a.create_time, '%Y-%m-%d %T' ) AS create_time, group_concat( i.filepath SEPARATOR ',' ) AS filepath, j.realname, l.name AS org_name, a.tenant_id FROM w_complain a LEFT JOIN r_form_consult_complain c ON c.complain_id = a.complain_id LEFT JOIN sc_service_contract d ON d.service_contract_id = c.consult_id and d.flag != - 1 LEFT JOIN wf_form w ON w.form_id = d.form_id LEFT JOIN w_complain_file g ON g.complain_id = a.complain_id LEFT JOIN s_file i ON i.file_id = g.file_id LEFT JOIN b_user j ON j.user_id = a.process_user_id LEFT JOIN r_user_tenant k ON k.user_id = j.user_id LEFT JOIN b_organization l ON l.organization_id = k.organization_id WHERE a.flag != -1 AND a.typef = 1 GROUP BY a.complain_id, w.form_id, a.user_id, a.typef, a.subject, a.content, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, a.process_time, a.flag,w.content,d.code,d.status,a.create_time,j.realname,l.name ) UNION ALL ( SELECT a.complain_id, d.form_id, a.user_id, a.typef, a.subject, a.content, (select name from b_organization where organization_id = a.organization_id) as serviceCompany, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, DATE_FORMAT(a.process_time, '%Y-%m-%d %T') AS process_time,a.flag, a.create_user_id, JSON_UNQUOTE(JSON_EXTRACT(d.content, '$.businessName')) AS business_name, JSON_UNQUOTE(JSON_EXTRACT(d.content, '$.code')) AS order_code, d.status AS order_status, DATE_FORMAT( a.create_time, '%Y-%m-%d %T' ) AS create_time, group_concat( i.filepath SEPARATOR ',' ) AS filepath, j.realname, l.name AS org_name, a.tenant_id FROM w_complain a LEFT JOIN r_form_consult_complain c ON c.complain_id = a.complain_id LEFT JOIN wf_form d ON d.form_id = c.consult_id and d.flag != -1 LEFT JOIN w_complain_file g ON g.complain_id = a.complain_id LEFT JOIN s_file i ON i.file_id = g.file_id LEFT JOIN b_user j ON j.user_id = a.process_user_id LEFT JOIN r_user_tenant k ON k.user_id = j.user_id LEFT JOIN b_organization l ON l.organization_id = k.organization_id WHERE a.flag != -1 and a.typef = 2 GROUP BY a.complain_id, d.form_id, a.user_id, a.typef, a.subject, a.content, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, a.process_time, a.flag,a.create_user_id, d.content,d.status,a.create_time,j.realname,l.name ) ) AS rs where rs.flag = 1
and rs.tenant_id = #{param.tenantId}
and rs.status = #{param.status}
and ( rs.subject like CONCAT('%',#{param.name},'%') or rs.content like CONCAT('%',#{param.name},'%') )
and rs.create_user_id = #{param.createUserId}
/*数据范围：所有*/
/*数据范围：当前租户*/ and rs.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and rs.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and rs.organization_id in
#{org.id}
/*数据范围：个人*/ and rs.create_user_id = #{userInfo.userId}
ORDER BY rs.create_time DESC

SELECT rs.* FROM ( ( SELECT a.complain_id, w.form_id, a.user_id, a.typef, a.subject, a.content, (select name from b_organization where organization_id = a.organization_id) as serviceCompany, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, DATE_FORMAT(a.process_time, '%Y-%m-%d %T') AS process_time,a.flag, a.create_user_id, JSON_UNQUOTE(JSON_EXTRACT(w.content, '$.businessName')) AS business_name, d.code AS order_code, d.status AS order_status, DATE_FORMAT( a.create_time, '%Y-%m-%d %T' ) AS create_time, group_concat( i.filepath SEPARATOR ',' ) AS filepath, j.realname, l.name AS org_name, a.tenant_id FROM w_complain a LEFT JOIN r_form_consult_complain c ON c.complain_id = a.complain_id LEFT JOIN sc_service_contract d ON d.service_contract_id = c.consult_id and d.flag != - 1 LEFT JOIN wf_form w ON w.form_id = d.form_id LEFT JOIN w_complain_file g ON g.complain_id = a.complain_id LEFT JOIN s_file i ON i.file_id = g.file_id LEFT JOIN b_user j ON j.user_id = a.process_user_id LEFT JOIN r_user_tenant k ON k.user_id = j.user_id LEFT JOIN b_organization l ON l.organization_id = k.organization_id WHERE a.flag != -1 AND a.typef = 1 GROUP BY a.complain_id, w.form_id, a.user_id, a.typef, a.subject, a.content, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, a.process_time, a.flag,w.content,d.code,d.status,a.create_time,j.realname,l.name ) UNION ALL ( SELECT a.complain_id, d.form_id, a.user_id, a.typef, a.subject, a.content, (select name from b_organization where organization_id = a.organization_id) as serviceCompany, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, DATE_FORMAT(a.process_time, '%Y-%m-%d %T') AS process_time,a.flag, a.create_user_id, JSON_UNQUOTE(JSON_EXTRACT(d.content, '$.businessName')) AS business_name, JSON_UNQUOTE(JSON_EXTRACT(d.content, '$.code')) AS order_code, d.status AS order_status, DATE_FORMAT( a.create_time, '%Y-%m-%d %T' ) AS create_time, group_concat( i.filepath SEPARATOR ',' ) AS filepath, j.realname, l.name AS org_name, a.tenant_id FROM w_complain a LEFT JOIN r_form_consult_complain c ON c.complain_id = a.complain_id LEFT JOIN wf_form d ON d.form_id = c.consult_id and d.flag != -1 LEFT JOIN w_complain_file g ON g.complain_id = a.complain_id LEFT JOIN s_file i ON i.file_id = g.file_id LEFT JOIN b_user j ON j.user_id = a.process_user_id LEFT JOIN r_user_tenant k ON k.user_id = j.user_id LEFT JOIN b_organization l ON l.organization_id = k.organization_id WHERE a.flag != -1 and a.typef = 2 GROUP BY a.complain_id, d.form_id, a.user_id, a.typef, a.subject, a.content, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, a.process_time, a.flag,a.create_user_id, d.content,d.status,a.create_time,j.realname,l.name ) ) AS rs where rs.flag = 1
and rs.tenant_id = #{param.tenantId}
and rs.status = #{param.status}
and ( rs.subject like CONCAT('%',#{param.name},'%') or rs.content like CONCAT('%',#{param.name},'%') )
and rs.create_user_id = #{param.createUserId}
/*数据范围：所有*/
/*数据范围：当前租户*/ and rs.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and rs.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and rs.organization_id in
#{org.id}
/*数据范围：个人*/ and rs.create_user_id = #{userInfo.userId}
ORDER BY rs.create_time DESC

select a.complain_id , a.user_id , a.typef , a.`subject` , a.content , (select name from b_organization where organization_id = a.organization_id) as service_company , a.company , a.contacts , a.phone , a.address , a.`status` , a.feedback , a.process_user_id , date_format(a.process_time, '%Y-%m-%d %T') as process_time , a.flag , b.order_code , b.contract_code , b.business_name , b.order_status , b.create_time , b.filepath , b.realname , b.org_name from w_complain a left join () as b on b.complain_id = a.complain_id where a.flag = 1
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.organization_id in
#{org.id}
/*数据范围：个人*/ and a.create_user_id = #{userInfo.userId}
and (a.`subject` like concat('%', #{listParam.searchMap.name}, '%') or a.content like concat('%', #{listParam.searchMap.name}, '%'))
and a.modify_time >= #{listParam.searchMap.starttime} AND a.modify_time <= #{listParam.searchMap.endtime}
and a.status = 0 and a.status = 2
order by a.create_time desc

select a.complain_id , a.user_id , a.typef , a.subject , a.content , (select name from b_organization where organization_id = a.organization_id) as service_company , a.company , a.contacts , a.phone , a.address , a.status , a.feedback , a.process_user_id , date_format(a.process_time, '%Y-%m-%d %T') AS process_time , a.flag , json_unquote(json_extract(w.content, '$.businessName')) AS business_name , json_unquote(json_extract(w.content, '$.code')) AS order_code , w.status AS order_status , date_format( a.create_time, '%Y-%m-%d %T' ) AS create_time , group_concat( i.filepath separator ',' ) AS filepath , j.realname , l.name AS org_name , w.form_id from w_complain a join r_form_consult_complain c on c.complain_id = a.complain_id join wf_form w on w.form_id = c.consult_id left join w_complain_file g on g.complain_id = a.complain_id left join s_file i on i.flag = 1 and i.file_id = g.file_id left join b_user j on j.flag = 1 and j.user_id = a.process_user_id left join r_user_tenant k on k.flag = 1 and k.user_id = j.user_id left join b_organization l on l.flag = 1 and l.organization_id = k.organization_id where a.complain_id = #{complainId} and a.typef = 2 and w.flag = 1 and a.flag = 1
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.organization_id in
#{org.id}
/*数据范围：个人*/ and a.create_user_id = #{userInfo.userId}
group by a.complain_id, a.user_id, a.typef, a.subject, a.content, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, a.process_time, a.flag, w.content, w.status, a.create_time, j.realname, l.name, w.form_id

select a.complain_id , a.user_id , a.typef , a.subject , a.content , (select name from b_organization where organization_id = a.organization_id) as service_company , a.company , a.contacts , a.phone , a.address , a.status , a.feedback , a.process_user_id , date_format(a.process_time, '%Y-%m-%d %T') AS process_time , a.flag , json_unquote(json_extract(d.content, '$.businessName')) AS business_name , json_unquote(json_extract(d.content, '$.code')) AS order_code , d.status AS order_status , date_format( a.create_time, '%Y-%m-%d %T' ) AS create_time , group_concat( i.filepath separator ',' ) AS filepath , j.realname , l.name AS org_name , b.name contract_name , b.code contract_code , d.form_id , b.service_contract_id as contract_id from w_complain a join r_form_consult_complain c on c.complain_id = a.complain_id join sc_service_contract b on b.service_contract_id = c.consult_id join wf_form d on d.form_id = c.consult_id left join w_complain_file g on g.complain_id = a.complain_id left join s_file i on i.flag = 1 and i.file_id = g.file_id left join b_user j on j.flag = 1 and j.user_id = a.process_user_id left join r_user_tenant k on k.flag = 1 and k.user_id = j.user_id left join b_organization l on l.flag = 1 and l.organization_id = k.organization_id where a.complain_id = #{complainId} and a.typef = 1 and d.flag = 1 and a.flag = 1
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.organization_id in
#{org.id}
/*数据范围：个人*/ and a.create_user_id = #{userInfo.userId}
group by a.complain_id, a.user_id, a.typef, a.subject, a.content, a.company, a.contacts, a.phone, a.address, a.status, a.feedback, a.process_user_id, a.process_time, a.flag, d.content, d.status, a.create_time, j.realname, l.name, b.name, b.code, d.form_id, b.service_contract_id
